select current_user,session_user,clock_timestamp() captured_at, jsonb_build_array((select jsonb_build_object('table','public.credit_accounts','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.credit_accounts x),
(select jsonb_build_object('table','public.credit_grants','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.credit_grants x),
(select jsonb_build_object('table','public.credit_transactions','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.credit_transactions x),
(select jsonb_build_object('table','public.essay_billing_decisions','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.essay_billing_decisions x),
(select jsonb_build_object('table','public.payment_events','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.payment_events x),
(select jsonb_build_object('table','public.payment_operations','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.payment_operations x),
(select jsonb_build_object('table','public.payment_orders','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.payment_orders x),
(select jsonb_build_object('table','public.math_billing_bindings','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.math_billing_bindings x),
(select jsonb_build_object('table','public.essay_evaluations','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.essay_evaluations x),
(select jsonb_build_object('table','public.math_evaluations','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from public.math_evaluations x),
(select jsonb_build_object('table','math_private.session_runs','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from math_private.session_runs x),
(select jsonb_build_object('table','essay_exam_private.runs','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from essay_exam_private.runs x),
(select jsonb_build_object('table','essay_beta_private.campaigns','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from essay_beta_private.campaigns x),
(select jsonb_build_object('table','essay_beta_private.exam_scope','count',count(*),'rowset_md5',md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by md5(to_jsonb(x)::text)),''))) from essay_beta_private.exam_scope x)) protected;